verify_commands.command:
rtk env PATH="$PWD/.venv/bin:$PATH" python -c 'import ast, io, re, subprocess, sys, tokenize
DIRECTIVE = re.compile(r"#\s*(?:noqa\b|type:\s*ignore\b|pragma:\s*no cover\b|(?:fmt|isort):\s*(?:on|off|skip)\b|pyright:|mypy:|ruff:|pylint:|nosec\b|coding[:=]|[A-Za-z][\w-]*-ok:)", re.I)
OWNERS = (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)
def src(ref, path):
    return subprocess.check_output(["git", "show", f"{ref}:{path}"], text=True)
def norm_ast(text):
    tree = ast.parse(text, type_comments=True)
    for ti in tree.type_ignores:
        ti.lineno = 0
    for node in ast.walk(tree):
        if isinstance(node, OWNERS) and node.body and isinstance(node.body[0], ast.Expr) and isinstance(node.body[0].value, ast.Constant) and isinstance(node.body[0].value.value, str):
            node.body = node.body[1:]
    return ast.dump(tree, include_attributes=False)
def directives(text):
    shebang = text.splitlines()[0] if text.startswith("#!") else ""
    comments = [tok.string for tok in tokenize.generate_tokens(io.StringIO(text).readline) if tok.type == tokenize.COMMENT and DIRECTIVE.search(tok.string)]
    return shebang, comments
bad_ast, bad_directives = [], []
for path in sys.argv[1:]:
    before, after = src("HEAD^", path), src("HEAD", path)
    if norm_ast(before) != norm_ast(after): bad_ast.append(path)
    if directives(before) != directives(after): bad_directives.append(path)
assert not bad_ast, f"non-docstring AST changes: {bad_ast}"
assert not bad_directives, f"directive/shebang changes: {bad_directives}"' scripts/jira_dc_epic_link_clear_probe.py scripts/jira_dc_field_readiness.py scripts/main_health_report.py scripts/mutation_gate.py scripts/mutation_sandbox.py scripts/probe_rebar.py scripts/rebar_duration_probe.py scripts/release_guards.py scripts/retarget_jira_project.py scripts/summarize_ci_failures.py
